+    function getQuestionInputs(name) {
+      return Array.from(form.querySelectorAll(`input[name="${name}"]`));
+    }
+
+    function setError(name, message) {
+      const field = form.querySelector(`[data-question="${name}"]`);
+      const error = document.getElementById(`${name}-error`);
+      field.classList.add('has-error');
+      error.textContent = message;
+      error.hidden = false;
+    }
+
+    function clearError(name) {
+      const field = form.querySelector(`[data-question="${name}"]`);
+      const error = document.getElementById(`${name}-error`);
+      field.classList.remove('has-error');
+      error.textContent = '';
+      error.hidden = true;
+    }
+
+    function validateSelections() {
+      let firstInvalidInput = null;
+
+      questionNames.forEach((name) => {
+        const inputs = getQuestionInputs(name);
+        const hasSelection = inputs.some((input) => input.checked);
+
+        if (!hasSelection) {
+          setError(name, 'Error: Select at least one answer.');
+          if (!firstInvalidInput) {
+            firstInvalidInput = inputs[0];
+          }
+          return;
+        }
+
+        clearError(name);
+      });
+
+      return firstInvalidInput;
+    }
+
+    function getScore() {
+      let score = 0;
+
+      questionNames.forEach((name) => {
+        const inputs = getQuestionInputs(name);
+        const isCorrect = inputs.every((input) => input.checked === (input.dataset.correct === 'true'));
+        if (isCorrect) {
+          score += 1;
+        }
+      });
+
+      return score;
+    }
+
+    function getSelectionsSummary() {
+      return questionNames
+        .map((name, index) => {
+          const selected = getQuestionInputs(name)
+            .filter((input) => input.checked)
+            .map((input) => input.value);
+          return `<p><strong>Question ${index + 1}:</strong> ${selected.join(', ')}</p>`;
+        })
+        .join('');
+    }
+
+    form.addEventListener('change', (event) => {
+      if (event.target instanceof HTMLInputElement && event.target.name) {
+        if (getQuestionInputs(event.target.name).some((input) => input.checked)) {
+          clearError(event.target.name);
+        }
+      }
+    });
+
+    form.addEventListener('submit', (event) => {
+      event.preventDefault();
+
+      const firstInvalidInput = validateSelections();
+      if (firstInvalidInput) {
+        resultBox.hidden = true;
+        firstInvalidInput.focus();
+        return;
+      }
+
+      const score = getScore();
+      resultBox.hidden = false;
+      resultBox.innerHTML = `
+        <p><strong>You scored ${score} out of ${questionNames.length}.</strong></p>
+        <p>Your selections have been recorded below.</p>
+        ${getSelectionsSummary()}
+      `;
+      resultBox.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
+    });
+  </script>
+</body>
