439.   <script>
440.     const form = document.getElementById('quiz-form');
441.     const resultBox = document.getElementById('results');
442.     const questionNames = ['question-1', 'question-2', 'question-3'];
443. 
444.     function getQuestionInputs(name) {
445.       return Array.from(form.querySelectorAll(`input[name="${name}"]`));
446.     }
447. 
448.     function setError(name, message) {
449.       const field = form.querySelector(`[data-question="${name}"]`);
450.       const error = document.getElementById(`${name}-error`);
451.       field.classList.add('has-error');
452.       error.textContent = message;
453.       error.hidden = false;
454.     }
455. 
456.     function clearError(name) {
457.       const field = form.querySelector(`[data-question="${name}"]`);
458.       const error = document.getElementById(`${name}-error`);
459.       field.classList.remove('has-error');
460.       error.textContent = '';
461.       error.hidden = true;
462.     }
463. 
464.     function validateSelections() {
465.       let firstInvalidInput = null;
466. 
467.       questionNames.forEach((name) => {
468.         const inputs = getQuestionInputs(name);
469.         const hasSelection = inputs.some((input) => input.checked);
470. 
471.         if (!hasSelection) {
472.           setError(name, 'Error: Select at least one answer.');
473.           if (!firstInvalidInput) {
474.             firstInvalidInput = inputs[0];
475.           }
476.           return;
477.         }
478. 
479.         clearError(name);
480.       });
481. 
482.       return firstInvalidInput;
483.     }
484. 
485.     function getScore() {
486.       let score = 0;
487. 
488.       questionNames.forEach((name) => {
489.         const inputs = getQuestionInputs(name);
490.         const isCorrect = inputs.every((input) => input.checked === (input.dataset.correct === 'true'));
491.         if (isCorrect) {
492.           score += 1;
493.         }
494.       });
495. 
496.       return score;
497.     }
498. 
499.     function getSelectionsSummary() {
500.       return questionNames
501.         .map((name, index) => {
502.           const selected = getQuestionInputs(name)
503.             .filter((input) => input.checked)
504.             .map((input) => input.value);
505.           return `<p><strong>Question ${index + 1}:</strong> ${selected.join(', ')}</p>`;
506.         })
507.         .join('');
508.     }
509. 
510.     form.addEventListener('change', (event) => {
511.       if (event.target instanceof HTMLInputElement && event.target.name) {
512.         if (getQuestionInputs(event.target.name).some((input) => input.checked)) {
513.           clearError(event.target.name);
514.         }
515.       }
516.     });
517. 
518.     form.addEventListener('submit', (event) => {
519.       event.preventDefault();
520. 
521.       const firstInvalidInput = validateSelections();
522.       if (firstInvalidInput) {
523.         resultBox.hidden = true;
524.         firstInvalidInput.focus();
525.         return;
526.       }
527. 
528.       const score = getScore();
529.       resultBox.hidden = false;
530.       resultBox.innerHTML = `
531.         <p><strong>You scored ${score} out of ${questionNames.length}.</strong></p>
532.         <p>Your selections have been recorded below.</p>
533.         ${getSelectionsSummary()}
534.       `;
535.       const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
536.       resultBox.scrollIntoView({ behavior: reduceMotion ? 'auto' : 'smooth', block: 'nearest' });
537.     });
538.   </script>
