       <section class="quiz-card" aria-labelledby="quiz-heading">
         <h2 id="quiz-heading" class="visually-hidden">Quiz questions</h2>

         <form id="quiz-form" novalidate>
           <div class="form-field" data-question="question-1">
             <fieldset aria-describedby="question-1-help question-1-error">
               <legend>1. Which of these are commonly used for front-end web development? <span aria-hidden="true">*</span></legend>
               <p id="question-1-help" class="field-help">Select at least one answer. Pick every language that developers regularly use to build interfaces in the browser.</p>
               <div class="choices">
                 <label class="choice" for="q1-html">
                   <input id="q1-html" type="checkbox" name="question-1" value="HTML" data-correct="true">
